const ee = require('@google/earthengine');
const privateKey = require('./temp/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeOkeechobee = ee.Geometry.Polygon(
    [
      [-81.08, 27.18], [-80.59, 27.18], [-80.59, 26.69], [-81.08, 26.69],
      [-81.08, 27.18]
    ]
  ).buffer(1000); // Buffer slightly to ensure full lake coverage

  const startDate = '2023-06-12';
  const endDate = '2023-06-13'; // Filter for a single day

  // Threshold for identifying potential cyanobacteria blooms.
  // NDCI (Normalized Difference Chlorophyll Index) is often used for this.
  // NDCI = (R709 - R665) / (R709 + R665) based on Sentinel-3 OLCI bands.
  // A threshold of >0.1 or >0.15 is often indicative of blooms. Let's use 0.1 for a conservative estimate.
  const bloomThreshold = 0.1;
  const targetCoveragePercentage = 30; // 30 percent

  // 2. Data Acquisition & Check
  // Using Sentinel-3 OLCI Level-2 WFR (Water Full Resolution) for surface reflectances.
  // Bands Oa08_reflectance (665 nm) and Oa10_reflectance (709 nm) are needed for NDCI.
  let collection = ee.ImageCollection('COPERNICUS/S3/OLCI')
    .filterDate(startDate, endDate)
    .filterBounds(lakeOkeechobee);

  const initialSize = await collection.size().getInfo();
  if (initialSize === 0) {
    console.log("No Sentinel-3 OLCI images found for Lake Okeechobee on June 12, 2023.");
    console.log("C1");
    return;
  }
  console.log(`Initial S3 images: ${initialSize}`);

  // Get the first image, assuming one image per day or picking the best one (e.g., least cloudy).
  // For a single day, taking the first is usually sufficient unless there are multiple full passes.
  // If multiple images exist, consider mosaicking or selecting the least cloudy.
  // For simplicity and given the single-day request, we'll try to get one representative image.
  let image = collection.mosaic(); // Mosaicking handles multiple images on the same day if any.

  // 3. Processing
  // Sentinel-3 OLCI cloud masking
  // https://developers.google.com/earth-engine/datasets/catalog/COPERNICUS_S3_OLCI#bands
  // Relevant quality flags in quality_flags band:
  // - L1_CLOUD_AMBIGUOUS (bit 1)
  // - L1_CLOUD_SURE (bit 2)
  // - CLOUD_IN_WATER (bit 26)
  // - CLOUD_AMBIGUOUS_IN_WATER (bit 27)
  // - L1_LAND (bit 0)
  // We want to mask out clouds and land.

  const qaBand = image.select('quality_flags');

  // Function to mask clouds and land
  const maskS3CloudsAndLand = (image) => {
    const cloudMask1 = qaBand.bitwiseAnd(1 << 1).eq(0); // L1_CLOUD_AMBIGUOUS
    const cloudMask2 = qaBand.bitwiseAnd(1 << 2).eq(0); // L1_CLOUD_SURE
    const cloudMask3 = qaBand.bitwiseAnd(1 << 26).eq(0); // CLOUD_IN_WATER
    const cloudMask4 = qaBand.bitwiseAnd(1 << 27).eq(0); // CLOUD_AMBIGUOUS_IN_WATER
    const landMask = qaBand.bitwiseAnd(1 << 0).eq(0); // L1_LAND

    const combinedMask = cloudMask1.and(cloudMask2).and(cloudMask3).and(cloudMask4).and(landMask);
    return image.updateMask(combinedMask);
  };

  image = maskS3CloudsAndLand(image);

  // Calculate NDCI (Normalized Difference Chlorophyll Index)
  // NDCI = (R709 - R665) / (R709 + R665)
  // Bands: Oa10_reflectance (709nm), Oa08_reflectance (665nm)
  const redEdge = image.select('Oa10_reflectance'); // ~709nm
  const red = image.select('Oa08_reflectance'); // ~665nm

  const ndci = redEdge.subtract(red).divide(redEdge.add(red)).rename('NDCI');

  // Mask out NDCI values outside a reasonable range (e.g., -1 to 1) just in case
  const maskedNdci = ndci.updateMask(ndci.gte(-1).and(ndci.lte(1)));

  // Calculate total water area within the geometry
  const waterAreaImage = maskedNdci.select('NDCI').gt(-2); // Create a mask of valid water pixels
  const totalWaterPixels = waterAreaImage.gt(0).rename('valid_water');

  const totalWaterCount = await totalWaterPixels.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeOkeechobee,
    scale: 300, // Sentinel-3 resolution is ~300m
    maxPixels: 1e9,
    tileScale: 4
  }).get('valid_water').getInfo();

  if (totalWaterCount === 0 || totalWaterCount === null) {
    console.log("No valid water pixels found after cloud/land masking for analysis.");
    console.log("C2");
    return;
  }
  const totalWaterAreaSqKm = totalWaterCount * (300 * 300) / 1e6; // Convert pixels to square kilometers

  // Identify bloom areas based on NDCI threshold
  const bloomPixels = maskedNdci.gt(bloomThreshold).rename('bloom_area');

  const bloomPixelCount = await bloomPixels.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeOkeechobee,
    scale: 300,
    maxPixels: 1e9,
    tileScale: 4
  }).get('bloom_area').getInfo();

  if (bloomPixelCount === null) {
    console.log("Calculation for bloom pixel count failed.");
    console.log("C3");
    return;
  }

  const bloomAreaSqKm = bloomPixelCount * (300 * 300) / 1e6; // Convert pixels to square kilometers

  // 4. Calculation
  let coveragePercentage = 0;
  if (totalWaterAreaSqKm > 0) {
    coveragePercentage = (bloomAreaSqKm / totalWaterAreaSqKm) * 100;
  }

  // 5. Validation & Final Answer
  console.log(`Lake Okeechobee Analysis - June 12, 2023`);
  console.log(`Total water pixels: ${totalWaterCount}`);
  console.log(`Total water area (km²): ${totalWaterAreaSqKm.toFixed(2)}`);
  console.log(`Bloom pixels (NDCI > ${bloomThreshold}): ${bloomPixelCount}`);
  console.log(`Bloom area (km²): ${bloomAreaSqKm.toFixed(2)}`);
  console.log(`Cyanobacteria coverage: ${coveragePercentage.toFixed(2)}%`);

  if (coveragePercentage > targetCoveragePercentage) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
